class Solution {
    bool check(const vector<int>& dist, double hour, int speed) {
        double time = 0;
        int n = dist.size();
        for (int i = 0; i < n - 1; ++i) {
            time += (dist[i] + speed - 1) / speed;
        }
        time += (double)dist[n - 1] / speed;
        return time <= hour;
    }
public:
    int minSpeedOnTime(vector<int>& dist, double hour) {
        int n = dist.size();
        if (n - 1 >= hour) return -1;

        int low = 1, high = 1e7, ans = -1;
        while (low <= high) {
            int mid = low + (high - low) / 2;
            if (check(dist, hour, mid)) {
                ans = mid;
                high = mid - 1;
            } else {
                low = mid + 1;
            }
        }
        return ans;
    }
};

class Solution {
    private boolean check(int[] dist, double hour, int speed) {
        double time = 0;
        int n = dist.length;
        for (int i = 0; i < n - 1; ++i) {
            time += (dist[i] + speed - 1) / speed;
        }
        time += (double)dist[n - 1] / speed;
        return time <= hour;
    }

    public int minSpeedOnTime(int[] dist, double hour) {
        int n = dist.length;
        if (n - 1 >= hour) return -1;

        int low = 1, high = 10_000_000, ans = -1;
        while (low <= high) {
            int mid = low + (high - low) / 2;
            if (check(dist, hour, mid)) {
                ans = mid;
                high = mid - 1;
            } else {
                low = mid + 1;
            }
        }
        return ans;
    }
}

/**
 * @param {number[]} dist
 * @param {number} hour
 * @return {number}
