var minSpeedOnTime = function(dist, hour) {
    const n = dist.length;
    if (n - 1 >= hour) return -1;

    function check(speed) {
        let time = 0;
        for (let i = 0; i < n - 1; ++i) {
            time += Math.ceil(dist[i] / speed);
        }
        time += dist[n - 1] / speed;
        return time <= hour;
    }

    let low = 1, high = 10000000, ans = -1;
    while (low <= high) {
        const mid = Math.floor((low + high) / 2);
        if (check(mid)) {
            ans = mid;
            high = mid - 1;
        } else {
            low = mid + 1;
        }
    }
    return ans;
};
